import{_ as r,C as i,c as l,o as g,a3 as s,G as o,j as t,a as e}from"./chunks/framework.Dokpd4od.js";const P=JSON.parse('{"title":"Attributes and packagings","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/products/attributes-and-packagings.md","filePath":"master/supply-chain/inventories/products/attributes-and-packagings.md","lastUpdated":1791902625000}'),c={name:"master/supply-chain/inventories/products/attributes-and-packagings.md"};function u(p,a,d,h,m,k){const n=i("ImagePopup");return g(),l("div",null,[a[0]||(a[0]=s('<h1 id="attributes-and-packagings" tabindex="-1">Attributes and packagings <a class="header-anchor" href="#attributes-and-packagings" aria-label="Permalink to &quot;Attributes and packagings&quot;">​</a></h1><p>Attributes and packagings describe how one product comes in different forms. An attribute makes variants, such as a lamp in red or blue. A packaging sets a pack size, such as a pack of 10. Both change how you order and move stock.</p><blockquote><p><strong>In simple words:</strong> Attributes answer &quot;which kind?&quot;. Packagings answer &quot;how many in a pack?&quot;.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Go to <code>Inventory → Settings → Manage Products</code> and turn on:</p><ul><li><strong>Variants</strong> to show <code>Configurations → Products → Attributes</code>.</li><li><strong>Packagings</strong> to show <code>Configurations → Products → Packagings</code>.</li></ul><p>See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p><h2 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h2><p>An attribute is a choice with a list of options. Examples from the sample data are <strong>Size</strong> (Select), <strong>Material</strong> (Select), <strong>Lense Type</strong> (Radio) and <strong>Speaker Color</strong> (Color).</p>',9)),o(n,{src:"/images1/inventory/prod_attributes_list.png",alt:"Attributes list with Name and Type columns"}),a[1]||(a[1]=t("h3",{id:"create-an-attribute",tabindex:"-1"},[e("Create an attribute "),t("a",{class:"header-anchor",href:"#create-an-attribute","aria-label":'Permalink to "Create an attribute"'},"​")],-1)),a[2]||(a[2]=t("ol",null,[t("li",null,[e("Go to "),t("code",null,"Inventory → Configurations → Products → Attributes"),e(".")]),t("li",null,[e("Click "),t("strong",null,"New Attribute"),e(".")]),t("li",null,"Fill the fields.")],-1)),o(n,{src:"/images1/inventory/prod_attribute_create.png",alt:"Attribute form named Size, type Select, with options Small Medium Large and extra price"}),a[3]||(a[3]=s('<ul><li><strong><em>Name:</em></strong> Required. The attribute name, such as <strong>Size</strong>.</li><li><strong><em>Type:</em></strong> <strong>Radio</strong>, <strong>Select</strong> or <strong>Color</strong>. It decides how a buyer picks the option.</li><li><strong><em>Options:</em></strong> Click <strong>Add to options</strong>. For each option set <strong>Name*</strong>, <strong>Color</strong> (for the Color type) and <strong>Extra Price*</strong> (default 0).</li></ul><ol start="4"><li>Click <strong>Create</strong>.</li></ol><h3 id="use-an-attribute-on-a-product" tabindex="-1">Use an attribute on a product <a class="header-anchor" href="#use-an-attribute-on-a-product" aria-label="Permalink to &quot;Use an attribute on a product&quot;">​</a></h3><p>Open the product, go to the <strong>Attributes</strong> tab and click <strong>Add Attribute</strong>. Pick the attribute and its values. Aureus creates one variant per combination. Each variant has its own <strong>On Hand</strong> and <strong>Forecasted</strong> quantity.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Adding or deleting attributes on a product deletes and recreates its variants. Custom changes on those variants are lost. Do this before you receive stock.</p></div><p>For the full variant walkthrough, see <a href="./../../../sales/sales/products-prices/product-variants.html">Product variants</a>.</p><h2 id="packagings" tabindex="-1">Packagings <a class="header-anchor" href="#packagings" aria-label="Permalink to &quot;Packagings&quot;">​</a></h2><p>A packaging is a named pack size for one product. Stock still counts in units. The packaging helps on order lines and in scanning.</p>',8)),o(n,{src:"/images1/inventory/prod_packagings_list.png",alt:"Packagings list with Name, Product, Qty, Barcode, Company and Package Type columns"}),a[4]||(a[4]=t("h3",{id:"create-a-packaging",tabindex:"-1"},[e("Create a packaging "),t("a",{class:"header-anchor",href:"#create-a-packaging","aria-label":'Permalink to "Create a packaging"'},"​")],-1)),a[5]||(a[5]=t("ol",null,[t("li",null,[e("Go to "),t("code",null,"Inventory → Configurations → Products → Packagings"),e(".")]),t("li",null,[e("Click "),t("strong",null,"New Packaging"),e(". A window opens.")])],-1)),o(n,{src:"/images1/inventory/prod_packaging_create.png",alt:"New packaging window with name Pack Of 10, product Car Dash Camera, quantity 10 and barcode"}),a[6]||(a[6]=s('<ul><li><strong><em>Name:</em></strong> Required. For example <strong>Pack Of 10</strong>.</li><li><strong><em>Product:</em></strong> Required. The product this pack belongs to, such as <strong>Car Dash Camera</strong>.</li><li><strong><em>Qty:</em></strong> Required. Units in one pack, such as 10.</li><li><strong><em>Barcode:</em></strong> Scan code for the pack, such as <strong>PACK-10</strong>.</li><li><strong><em>Company:</em></strong> Owner company.</li><li><strong><em>Package Type:</em></strong> A box type, when Packages is on.</li><li><strong><em>Routes:</em></strong> Routes that apply to this pack.</li></ul><ol start="3"><li>Click <strong>Create</strong>.</li></ol><p>On a receipt or delivery, the <strong>Packaging</strong> column on a move line lets you choose the pack. The <strong>Demand</strong> then follows the pack quantity.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A packaging is not the same as a package. A packaging is a pack size. A package is a real box you can track. See <a href="./../tracking/packages.html">Packages</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../../sales/sales/configuration/product-attributes.html">Product attributes in Sales</a></li><li><a href="./../../../sales/sales/configuration/packagings.html">Packagings in Sales</a></li><li><a href="./configure-product.html">Configure a product</a></li><li><a href="./../tracking/packages.html">Packages</a></li></ul>',6))])}const f=r(c,[["render",u]]);export{P as __pageData,f as default};
